-- ============================================================
-- REPETECO — carga 2 de 3: acervo de demonstração
-- Rode DEPOIS da carga 1. Cole ESTE ARQUIVO INTEIRO no SQL Editor e
-- clique em Run. Pode ser repetido (não duplica).
--
-- Cria a loja "Acervo Repeteco" (origem 'demonstracao', só online),
-- ligada à primeira conta administradora, com 46 peças: roupas,
-- calçados (com numeração), acessórios, casa e cultura, várias em
-- promoção. A página da loja avisa que é um acervo de demonstração.
--
-- Fotos: Unsplash (licença Unsplash, uso livre, sem ocupar o Storage
-- do Supabase — o site pede a cada tela só a largura necessária).
-- Créditos no texto alternativo de cada foto. Revise as fotos no feed e
-- troque/exclua pelo painel (Minhas peças) as que não agradarem.
--
-- Para remover tudo depois: supabase/carga/3_remover_demonstracao.sql
-- ============================================================

do $$
declare
  v_admin uuid := (select id from public.profiles where role = 'admin' order by created_at limit 1);
  v_loja uuid;
begin
  if v_admin is null then
    raise exception 'Nenhuma conta administradora encontrada. Crie a sua conta e torne-a admin (README) antes desta carga.';
  end if;

  select id into v_loja from public.brechos where slug = 'acervo-repeteco';
  if v_loja is null then
    insert into public.brechos (nome, slug, descricao, cidade, categorias, modalidade, status, origem, user_id, instagram)
    values ('Acervo Repeteco', 'acervo-repeteco',
            'Acervo de demonstração do Repeteco: peças fotografadas para mostrar como o feed, a busca, as promoções e a página de cada peça funcionam.',
            'São Paulo', '["brechó","moda vintage","calçados","casa e decoração"]'::jsonb, 'online', 'approved', 'demonstracao', v_admin, null)
    returning id into v_loja;
  end if;

  if exists (select 1 from public.publicacoes where brecho_id = v_loja) then
    raise notice 'O acervo de demonstração já tem peças; nada foi inserido.';
    return;
  end if;

  insert into public.publicacoes (brecho_id, titulo, descricao, imagem_url, thumb_url, imagens, alt_text, tipo, tamanho, preco, preco_original, condicao, estilo, genero, disponivel, status, created_at)
  select v_loja, t.titulo, t.descricao, t.imagem_url, t.thumb_url, t.imagens, t.alt_text, t.tipo, t.tamanho, t.preco, t.preco_original, t.condicao, t.estilo, t.genero,
         true, 'publicado', now() - (t.ordem * interval '7 hours')
  from (values
  ('Vestido curto vermelho', 'Vestido curto de alcinha, tecido com caimento leve. Busto 84 cm, comprimento 82 cm.', 'https://images.unsplash.com/photo-1564462641887-845a1eee6b13?auto=format&fit=crop&w=1400&q=80', 'https://images.unsplash.com/photo-1564462641887-845a1eee6b13?auto=format&fit=crop&w=480&q=80', '[{"url": "https://images.unsplash.com/photo-1564462641887-845a1eee6b13?auto=format&fit=crop&w=1400&q=80", "thumb_url": "https://images.unsplash.com/photo-1564462641887-845a1eee6b13?auto=format&fit=crop&w=480&q=80", "alt": "Vestido curto vermelho. Foto de Priscilla Du Preez (Unsplash)", "path": null, "thumb_path": null}]'::jsonb, 'Vestido curto vermelho. Foto de Priscilla Du Preez (Unsplash)', 'vestido', 'P', 89, null, 'otimo', 'festa', 'feminino', 0),
  ('Vestido floral anos 90', 'Estampa floral em vermelho, verde e branco, viscose. Comprimento midi.', 'https://images.unsplash.com/photo-1579986736295-338a3a637862?auto=format&fit=crop&w=1400&q=80', 'https://images.unsplash.com/photo-1579986736295-338a3a637862?auto=format&fit=crop&w=480&q=80', '[{"url": "https://images.unsplash.com/photo-1579986736295-338a3a637862?auto=format&fit=crop&w=1400&q=80", "thumb_url": "https://images.unsplash.com/photo-1579986736295-338a3a637862?auto=format&fit=crop&w=480&q=80", "alt": "Vestido floral anos 90. Foto de Isi Parente (Unsplash)", "path": null, "thumb_path": null}]'::jsonb, 'Vestido floral anos 90. Foto de Isi Parente (Unsplash)', 'vestido', 'M', 120, 160, 'otimo', 'anos-90', 'feminino', 1),
  ('Vestido branco de alcinha', 'Algodão leve, ótimo para o verão. Pequeno sinal de uso na barra.', 'https://images.unsplash.com/photo-1570468100438-cd4e938b1d11?auto=format&fit=crop&w=1400&q=80', 'https://images.unsplash.com/photo-1570468100438-cd4e938b1d11?auto=format&fit=crop&w=480&q=80', '[{"url": "https://images.unsplash.com/photo-1570468100438-cd4e938b1d11?auto=format&fit=crop&w=1400&q=80", "thumb_url": "https://images.unsplash.com/photo-1570468100438-cd4e938b1d11?auto=format&fit=crop&w=480&q=80", "alt": "Vestido branco de alcinha. Foto de Brittani Burns (Unsplash)", "path": null, "thumb_path": null}]'::jsonb, 'Vestido branco de alcinha. Foto de Brittani Burns (Unsplash)', 'vestido', 'M', 95, null, 'bom', 'boho', 'feminino', 2),
  ('Saia jeans azul', 'Jeans 100% algodão, cintura alta, comprimento acima do joelho.', 'https://images.unsplash.com/photo-1430151569685-d540d6f4f998?auto=format&fit=crop&w=1400&q=80', 'https://images.unsplash.com/photo-1430151569685-d540d6f4f998?auto=format&fit=crop&w=480&q=80', '[{"url": "https://images.unsplash.com/photo-1430151569685-d540d6f4f998?auto=format&fit=crop&w=1400&q=80", "thumb_url": "https://images.unsplash.com/photo-1430151569685-d540d6f4f998?auto=format&fit=crop&w=480&q=80", "alt": "Saia jeans azul. Foto de Dani Marroquin (Unsplash)", "path": null, "thumb_path": null}]'::jsonb, 'Saia jeans azul. Foto de Dani Marroquin (Unsplash)', 'saia', '38', 65, null, 'otimo', 'y2k', 'feminino', 3),
  ('Saia midi marrom', 'Saia midi em tom caramelo, forrada, com zíper lateral.', 'https://images.unsplash.com/photo-1584530382968-71752f02bddb?auto=format&fit=crop&w=1400&q=80', 'https://images.unsplash.com/photo-1584530382968-71752f02bddb?auto=format&fit=crop&w=480&q=80', '[{"url": "https://images.unsplash.com/photo-1584530382968-71752f02bddb?auto=format&fit=crop&w=1400&q=80", "thumb_url": "https://images.unsplash.com/photo-1584530382968-71752f02bddb?auto=format&fit=crop&w=480&q=80", "alt": "Saia midi marrom. Foto de Chi Lok TSANG (Unsplash)", "path": null, "thumb_path": null}]'::jsonb, 'Saia midi marrom. Foto de Chi Lok TSANG (Unsplash)', 'saia', '40', 78, 110, 'otimo', 'minimalista', 'feminino', 4),
  ('Jaqueta jeans lavagem média', 'Modelagem oversized, botões de metal originais. Ombro a ombro 52 cm.', 'https://images.unsplash.com/photo-1584222604595-014be9ea02c2?auto=format&fit=crop&w=1400&q=80', 'https://images.unsplash.com/photo-1584222604595-014be9ea02c2?auto=format&fit=crop&w=480&q=80', '[{"url": "https://images.unsplash.com/photo-1584222604595-014be9ea02c2?auto=format&fit=crop&w=1400&q=80", "thumb_url": "https://images.unsplash.com/photo-1584222604595-014be9ea02c2?auto=format&fit=crop&w=480&q=80", "alt": "Jaqueta jeans lavagem média. Foto de Adam Bixby (Unsplash)", "path": null, "thumb_path": null}]'::jsonb, 'Jaqueta jeans lavagem média. Foto de Adam Bixby (Unsplash)', 'jaqueta', 'G', 140, null, 'otimo', 'vintage', 'unissex', 5),
  ('Jaqueta jeans azul clássica', 'Jaqueta jeans tradicional com bolsos frontais. Leve desbotado natural.', 'https://images.unsplash.com/photo-1575133377067-d14b05a96100?auto=format&fit=crop&w=1400&q=80', 'https://images.unsplash.com/photo-1575133377067-d14b05a96100?auto=format&fit=crop&w=480&q=80', '[{"url": "https://images.unsplash.com/photo-1575133377067-d14b05a96100?auto=format&fit=crop&w=1400&q=80", "thumb_url": "https://images.unsplash.com/photo-1575133377067-d14b05a96100?auto=format&fit=crop&w=480&q=80", "alt": "Jaqueta jeans azul clássica. Foto de Skylar Michael (Unsplash)", "path": null, "thumb_path": null}]'::jsonb, 'Jaqueta jeans azul clássica. Foto de Skylar Michael (Unsplash)', 'jaqueta', 'M', 120, null, 'bom', 'casual', 'unissex', 6),
  ('Jaqueta de couro marrom', 'Couro legítimo, forro em bom estado, zíper funcionando.', 'https://images.unsplash.com/photo-1547913817-0ebfc721bc85?auto=format&fit=crop&w=1400&q=80', 'https://images.unsplash.com/photo-1547913817-0ebfc721bc85?auto=format&fit=crop&w=480&q=80', '[{"url": "https://images.unsplash.com/photo-1547913817-0ebfc721bc85?auto=format&fit=crop&w=1400&q=80", "thumb_url": "https://images.unsplash.com/photo-1547913817-0ebfc721bc85?auto=format&fit=crop&w=480&q=80", "alt": "Jaqueta de couro marrom. Foto de Alec Favale (Unsplash)", "path": null, "thumb_path": null}]'::jsonb, 'Jaqueta de couro marrom. Foto de Alec Favale (Unsplash)', 'jaqueta', 'G', 280, 380, 'otimo', 'anos-70', 'masculino', 7),
  ('Jaqueta de couro preta', 'Couro preto com zíperes metálicos. Marcas leves de uso nas mangas.', 'https://images.unsplash.com/photo-1591904571049-16d4e0119d93?auto=format&fit=crop&w=1400&q=80', 'https://images.unsplash.com/photo-1591904571049-16d4e0119d93?auto=format&fit=crop&w=480&q=80', '[{"url": "https://images.unsplash.com/photo-1591904571049-16d4e0119d93?auto=format&fit=crop&w=1400&q=80", "thumb_url": "https://images.unsplash.com/photo-1591904571049-16d4e0119d93?auto=format&fit=crop&w=480&q=80", "alt": "Jaqueta de couro preta. Foto de Altin Ferreira (Unsplash)", "path": null, "thumb_path": null}]'::jsonb, 'Jaqueta de couro preta. Foto de Altin Ferreira (Unsplash)', 'jaqueta', 'M', 260, null, 'bom', 'grunge', 'unissex', 8),
  ('Blazer branco alfaiataria', 'Blazer forrado, um botão, ombreira leve.', 'https://images.unsplash.com/photo-1542595735-19bfcdc1feb0?auto=format&fit=crop&w=1400&q=80', 'https://images.unsplash.com/photo-1542595735-19bfcdc1feb0?auto=format&fit=crop&w=480&q=80', '[{"url": "https://images.unsplash.com/photo-1542595735-19bfcdc1feb0?auto=format&fit=crop&w=1400&q=80", "thumb_url": "https://images.unsplash.com/photo-1542595735-19bfcdc1feb0?auto=format&fit=crop&w=480&q=80", "alt": "Blazer branco alfaiataria. Foto de Brooke Cagle (Unsplash)", "path": null, "thumb_path": null}]'::jsonb, 'Blazer branco alfaiataria. Foto de Brooke Cagle (Unsplash)', 'blazer', 'M', 150, null, 'otimo', 'alfaiataria', 'feminino', 9),
  ('Blazer marrom de lã', 'Lã fria, dois botões, bolsos com lapela.', 'https://images.unsplash.com/photo-1552760647-0a848d97bff3?auto=format&fit=crop&w=1400&q=80', 'https://images.unsplash.com/photo-1552760647-0a848d97bff3?auto=format&fit=crop&w=480&q=80', '[{"url": "https://images.unsplash.com/photo-1552760647-0a848d97bff3?auto=format&fit=crop&w=1400&q=80", "thumb_url": "https://images.unsplash.com/photo-1552760647-0a848d97bff3?auto=format&fit=crop&w=480&q=80", "alt": "Blazer marrom de lã. Foto de Elisei Abiculesei (Unsplash)", "path": null, "thumb_path": null}]'::jsonb, 'Blazer marrom de lã. Foto de Elisei Abiculesei (Unsplash)', 'blazer', 'G', 170, 230, 'otimo', 'classico', 'masculino', 10),
  ('Blazer vermelho', 'Vermelho intenso, ombreiras marcadas, botões dourados.', 'https://images.unsplash.com/photo-1583119906980-a3ca5e61f648?auto=format&fit=crop&w=1400&q=80', 'https://images.unsplash.com/photo-1583119906980-a3ca5e61f648?auto=format&fit=crop&w=480&q=80', '[{"url": "https://images.unsplash.com/photo-1583119906980-a3ca5e61f648?auto=format&fit=crop&w=1400&q=80", "thumb_url": "https://images.unsplash.com/photo-1583119906980-a3ca5e61f648?auto=format&fit=crop&w=480&q=80", "alt": "Blazer vermelho. Foto de Sayla Brown (Unsplash)", "path": null, "thumb_path": null}]'::jsonb, 'Blazer vermelho. Foto de Sayla Brown (Unsplash)', 'blazer', 'P', 135, null, 'otimo', 'anos-80', 'feminino', 11),
  ('Suéter de tricô off-white', 'Tricô grosso de trama fechada, gola careca.', 'https://images.unsplash.com/photo-1491245257527-395e9c480145?auto=format&fit=crop&w=1400&q=80', 'https://images.unsplash.com/photo-1491245257527-395e9c480145?auto=format&fit=crop&w=480&q=80', '[{"url": "https://images.unsplash.com/photo-1491245257527-395e9c480145?auto=format&fit=crop&w=1400&q=80", "thumb_url": "https://images.unsplash.com/photo-1491245257527-395e9c480145?auto=format&fit=crop&w=480&q=80", "alt": "Suéter de tricô off-white. Foto de Victoria Berman (Unsplash)", "path": null, "thumb_path": null}]'::jsonb, 'Suéter de tricô off-white. Foto de Victoria Berman (Unsplash)', 'tricot', 'M', 98, null, 'otimo', 'minimalista', 'unissex', 12),
